CREATE FUNCTION public.pm_billing_schedule_fiscal_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.pm_billing_can_act_fiscal() AND ((TG_OP='INSERT' AND NEW.billing_status::text IN ('issued','paid')) OR (TG_OP='UPDATE' AND NEW.billing_status IS DISTINCT FROM OLD.billing_status AND (NEW.billing_status::text IN ('issued','paid') OR OLD.billing_status::text IN ('issued','paid')))) THEN RAISE EXCEPTION 'Project fiscal access required' USING ERRCODE='42501';END IF;RETURN NEW;END $$;
CREATE TRIGGER pm_billing_schedule_fiscal_guard BEFORE INSERT OR UPDATE ON public.pm_payment_schedule_items FOR EACH ROW EXECUTE FUNCTION public.pm_billing_schedule_fiscal_guard();